import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.Bzd4OF_4.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),r={name:"architecture.md"};function i(s,e,c,d,h,l){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>TALLY uses a modular monolith: one Go deployable with explicit internal bounded-context boundaries, a React SPA, and PostgreSQL schemas owned by their corresponding modules.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>React SPA → HTTP/API adapters → application modules → owned PostgreSQL schemas</span></span>
<span class="line"><span>                                      ↘ outbox and integration workers</span></span></code></pre></div><p>The design is local-first and cost-conscious for learning. Azure has a separate demonstration/production-qualification path; the learning deployment is not represented as production-qualified.</p><h2 id="ownership-boundaries" tabindex="-1">Ownership boundaries <a class="header-anchor" href="#ownership-boundaries" aria-label="Permalink to &quot;Ownership boundaries&quot;">​</a></h2><p>Each finance fact has one owning bounded context. Modules communicate through application contracts and events. They do not reach into another module’s adapters or database schema. Shared packages contain technical primitives only.</p><p>See the <a href="https://github.com/toanle88/Tally/blob/main/docs/specs/system_design/01_solution_architecture_overview_v1.0.md" target="_blank" rel="noreferrer">solution architecture overview</a> for the canonical architecture.</p>`,7)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
